#!/usr/bin/env python3
"""Remove generator/vendor leakage from the products in `products/`.

A product you sell must not carry traces of how it was produced. This script
strips, from every shipped file:

  * absolute developer file paths (they leak the author's real name, their
    OneDrive/Desktop layout, and the generator's internal folder structure),
  * "Generated by <generator>" attribution in headers, footers and JSON,
  * generator branding in source-file banner comments,
  * the generator's package name in package.json,
  * a hardcoded default API key that would ship to every buyer,
  * demo data belonging to a *different* product (copy-paste contamination).

Product names, taglines and support contacts come from a per-product profile at
the top of this file, so the output reads like a hand-made product.

    python scripts/scrub_identity.py --dry-run
    python scripts/scrub_identity.py
"""

from __future__ import annotations

import argparse
import json
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path

for _s in (sys.stdout, sys.stderr):
    try:
        _s.reconfigure(encoding="utf-8", errors="replace")
    except (AttributeError, ValueError):
        pass

ROOT = Path(__file__).resolve().parent.parent
PRODUCTS = ROOT / "products"

# Where buyers should send support mail. Override on the command line with
# --support-email before publishing.
DEFAULT_SUPPORT_EMAIL = "support@example.com"

# Author name used in copyright lines.
DEFAULT_AUTHOR = "The Vendor"

TEXT_EXT = {".js", ".jsx", ".ts", ".tsx", ".json", ".md", ".html", ".css",
            ".yml", ".yaml", ".sql", ".txt", ".env", ".example", ".svg", ""}
SKIP_DIRS = {"node_modules", ".git", "dist", "build", "coverage", "screenshots",
             ".artifacts", ".history"}

# Demo content belonging to an unrelated product that got copied into the
# seed scripts. Buyers see this the moment they run `npm run seed`.
CONTAMINATION = [
    ("LumiCore SoundPro Wireless ANC Headphones", "Studio Wireless ANC Headphones"),
    ("Welcome to LumiCorePro!", "Welcome!"),
]


@dataclass
class Profile:
    """Per-product identity used when rewriting branding."""
    slug: str
    title: str
    tagline: str = ""
    support_email: str = DEFAULT_SUPPORT_EMAIL
    docs_url: str = ""

    @property
    def backend_pkg(self) -> str:
        return f"{self.slug}-backend"

    @property
    def frontend_pkg(self) -> str:
        return f"{self.slug}-frontend"


PROFILES: dict[str, Profile] = {
    "apex": Profile("apex", "Apex", "Precision commerce for ambitious brands"),
    "aurelia-estates": Profile("aurelia-estates", "Aurelia Estates",
                               "Exceptional residences, curated for the discerning."),
    "aurum-fitness": Profile("aurum-fitness", "Aurum Fitness",
                             "Coaching that compounds, for every athlete."),
    "claimflow-ai": Profile("claimflow-ai", "ClaimFlow",
                             "Insurance claims, processed at the speed of reality."),
    "flowpilot": Profile("flowpilot", "FlowPilot",
                         "Projects, billing and insight in one calm workspace."),
    "meridian-capital": Profile("meridian-capital", "Meridian Capital",
                                "Institutional-grade portfolio intelligence."),
    "nuage-events": Profile("nuage-events", "Nuage Events",
                            "Events worth travelling for."),
    "prestige-studio": Profile("prestige-studio", "Prestige Studio",
                               "A studio site with the craft to match the work."),
    "resupro": Profile("resupro", "ResuPro",
                       "Resumes that get you the interview."),
    "saffron-voyage": Profile("saffron-voyage", "Saffron Voyage",
                              "Curated journeys across the Mediterranean."),
    "studio-lumen": Profile("studio-lumen", "Studio Lumen",
                            "Light, considered, and precisely captured."),
}

# Absolute developer paths. These leak the author's real account name, their
# OneDrive/Desktop layout, and the generator's internal folder structure.
#
# The path segment is matched loosely on purpose: real Windows paths contain
# spaces ("C:/Users/AZAM COMPUTERS/..."), and in JSON the separators may appear
# as single or doubled backslashes, so `[/\\]+` covers every form.
PATH_PATTERNS = [
    re.compile(r"[A-Za-z]:[/\\]+[^\"'\n]*?generated-projects[/\\]+[^\"'\n]*"),
    re.compile(r"[A-Za-z]:[/\\]+[^\"'\n]*?project-rules[/\\]*[^\"'\n]*"),
]


@dataclass
class Change:
    path: Path
    kind: str
    count: int = 1


@dataclass
class Report:
    name: str
    changes: list[Change] = field(default_factory=list)

    @property
    def total(self) -> int:
        return sum(c.count for c in self.changes)


def scrub_paths(text: str) -> tuple[str, int]:
    """Replace absolute developer paths with a portable, relative marker."""
    n = 0
    for rx in PATH_PATTERNS:
        text, k = rx.subn("<project-root>", text)
        n += k
    return text, n


def scrub_attribution(text: str, prof: Profile) -> tuple[str, int]:
    """Remove generator attribution and rebrand banner comments."""
    n = 0
    subs = [
        # Product identity first, so nothing below can reintroduce the vendor.
        (r"lumicorepro-core", prof.slug),
        (r"lumicorepro-design-engine", f"{prof.slug}-design-system"),
        # Lowercase form appears inside identifiers, container names and
        # hostnames, so it becomes the product slug.
        (r"\blumicorepro\b", prof.slug),
        (r"\blumicorepro-nginx\b", f"{prof.slug}-nginx"),
        (r"\blumicorepro-backend\b", prof.backend_pkg),
        # Mixed-case brand name in prose and banner comments. The source tree
        # spells it both `LumiCorePro` and `LumicorePro`, so match either.
        (r"LumiCorePro", prof.title),
        (r"LumicorePro", prof.title),
        (r"LUMICOREPRO", prof.title.upper()),
        (r"\bLumicore\b", prof.title),
        (r"\bLumicore\s+Audio\b", f"{prof.title} Audio"),
        (r"generated by the Lumi[Cc]orePro[^\n]*", f"{prof.title} — official release"),
        (r"[Gg]enerated by Lumi[Cc]orePro(\s*\|\s*Support)", rf"{prof.title}\1"),
        (r"<!--\s*LUMICORE_LICENSE:START\s*-->", "<!-- LICENSE:START -->"),
        (r"<!--\s*LUMICORE_LICENSE:END\s*-->", "<!-- LICENSE:END -->"),
        (r"LUMICORE_LICENSE", "LICENSE"),
        # Lowercase identifiers that survive the brand rules above.
        (r"\blumicore_db\b", f"{prof.slug}_db"),
        (r"\blumicore-nginx\b", f"{prof.slug}-nginx"),
        (r"\bLumiCore Audio\b", f"{prof.title} Audio"),
        # Comment/attribute markers used by the build tooling.
        (r"LUMICORE_SCHEMA", "SCHEMA"),
        (r"LUMICORE_I18N", "I18N"),
        (r"'lumicore:analytics'", f"'{prof.slug}:analytics'"),
        (r'"lumicore:analytics"', f'"{prof.slug}:analytics"'),
        (r"LUMICORE_HREFLANG", "HREFLANG"),
        # Generic catch-alls for internal identifiers and comment markers that
        # use the vendor name as a prefix, e.g. LumicoreEventBus,
        # lumicore_consent, LUMICORE_REPAIR. Rebase the prefix and keep the
        # suffix so the identifier still makes sense.
        (r"\bLumicore(?=[A-Z])", prof.title.replace(" ", "")),
        (r"\blumicore(?=[-_a-z0-9])", prof.slug.replace("-", "")),
        (r"\bLUMICORE_", "APP_"),
    ]
    for pat, rep in subs:
        text, k = re.subn(pat, rep, text)
        n += k
    return text, n


def scrub_secrets(text: str) -> tuple[str, int]:
    """Remove a hardcoded default API key that would ship to every buyer."""
    n = 0
    text, k = re.subn(
        r"(process\.env\.VALID_API_KEYS\s*\|\|\s*)'[^']*'",
        r"\1''", text)
    n += k
    text, k = re.subn(r"\blumicore_dev_key_\d+\b", "", text)
    n += k
    return text, n


def scrub_contamination(text: str, prof: Profile) -> tuple[str, int]:
    n = 0
    for old, new in CONTAMINATION:
        text, k = re.subn(re.escape(old), new, text)
        n += k
    return text, n


def scrub_contact(text: str, email: str) -> tuple[str, int]:
    n = 0
    text, k = re.subn(r"support@lumicorepro\.com", email, text, flags=re.I)
    n += k
    return text, n


def scrub_package_names(p: Path, prof: Profile) -> list[Change]:
    """Rename the generator's package name in the npm manifests."""
    out = []
    for rel, new_name in (
        ("backend/package.json", prof.backend_pkg),
        ("frontend/package.json", prof.frontend_pkg),
    ):
        f = p / rel
        if not f.is_file():
            continue
        raw = f.read_text(encoding="utf-8", errors="replace")
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            continue
        if data.get("name") in (None, prof.backend_pkg, prof.frontend_pkg):
            continue
        if "lumicore" not in data.get("name", "").lower():
            continue
        data["name"] = new_name
        f.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")
        out.append(Change(f, "package-name", 1))
    return out


def iter_text_files(p: Path):
    for f in p.rglob("*"):
        if not f.is_file():
            continue
        if any(part in SKIP_DIRS for part in f.parts):
            continue
        if f.suffix.lower() in TEXT_EXT:
            yield f


def scrub_product(p: Path, prof: Profile, email: str, dry: bool) -> Report:
    rep = Report(name=p.name)
    if dry:
        # Dry run: report what would change without writing.
        for f in iter_text_files(p):
            text = f.read_text(encoding="utf-8", errors="replace")
            _, a = scrub_paths(text)
            _, b = scrub_attribution(text, prof)
            _, c = scrub_secrets(text)
            _, d = scrub_contamination(text, prof)
            _, e = scrub_contact(text, email)
            if a: rep.changes.append(Change(f, "dev-path", a))
            if b: rep.changes.append(Change(f, "ai-attribution", b))
            if c: rep.changes.append(Change(f, "hardcoded-key", c))
            if d: rep.changes.append(Change(f, "cross-product-data", d))
            if e: rep.changes.append(Change(f, "vendor-contact", e))
        return rep

    for f in iter_text_files(p):
        try:
            text = f.read_text(encoding="utf-8", errors="replace")
        except OSError:
            continue
        new = text
        # NOTE: keep the returned text from every scrubber — discarding it here
        # silently reports the edit count while writing the original content.
        new, a = scrub_paths(new)
        new, b = scrub_attribution(new, prof)
        new, c = scrub_secrets(new)
        new, d = scrub_contamination(new, prof)
        new, e = scrub_contact(new, email)
        if new != text:
            try:
                f.write_text(new, encoding="utf-8")
            except OSError:
                continue
        if a: rep.changes.append(Change(f, "dev-path", a))
        if b: rep.changes.append(Change(f, "ai-attribution", b))
        if c: rep.changes.append(Change(f, "hardcoded-key", c))
        if d: rep.changes.append(Change(f, "cross-product-data", d))
        if e: rep.changes.append(Change(f, "vendor-contact", e))

    rep.changes.extend(scrub_package_names(p, prof))
    return rep


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__,
                                 formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--dry-run", action="store_true")
    ap.add_argument("--only", help="filter to one product")
    ap.add_argument("--support-email", default=DEFAULT_SUPPORT_EMAIL)
    ap.add_argument("--author", default=DEFAULT_AUTHOR)
    a = ap.parse_args()

    if not PRODUCTS.is_dir():
        print(f"No {PRODUCTS} directory", file=sys.stderr)
        return 2

    dirs = sorted(q for q in PRODUCTS.iterdir()
                  if q.is_dir() and not q.name.startswith("."))
    if a.only:
        dirs = [q for q in dirs if a.only in q.name]
    if not dirs:
        print("No matching products", file=sys.stderr)
        return 2

    print(f"=== scrub_identity: {'DRY RUN' if a.dry_run else 'APPLY'} "
          f"({len(dirs)} product(s), support={a.support_email}) ===")

    grand = 0
    for d in dirs:
        prof = PROFILES.get(d.name)
        if prof is None:
            print(f"-- {d.name}: SKIPPED (no profile defined)")
            continue
        rep = scrub_product(d, prof, a.support_email, a.dry_run)
        grand += rep.total
        kinds: dict[str, int] = {}
        for c in rep.changes:
            kinds[c.kind] = kinds.get(c.kind, 0) + c.count
        summary = ", ".join(f"{k}={v}" for k, v in sorted(kinds.items())) or "clean"
        print(f"-- {d.name:20} {rep.total:>5} edit(s)  {summary}")

    print(f"\n=== {grand} edit(s) across {len(dirs)} product(s) ===")
    return 0


if __name__ == "__main__":
    sys.exit(main())